#!/usr/bin/env python3
"""Loopback-only ESP protocol fixture for dedicated Android test devices.

adb reverse tcp:18080 tcp:18080
Run instrumentation with -Pandroid.testInstrumentationRunnerArguments.espFixture=true.
This simulates firmware responses; it does not validate Wi-Fi or physical hardware.
"""
import base64
import json
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse, parse_qs

JPEG = base64.b64decode("")
FACE = base64.b64decode("")
CURRENT_JPEG = JPEG
LOCK = threading.Lock()
DEFAULT = dict(device_id="fixture-esp", mode="ap", connected=False, camera_ready=True, restarting=False)
STATE = dict(DEFAULT)
STREAMING = True


class Handler(BaseHTTPRequestHandler):
    def log_message(self, *_):
        pass  # Never log authorization or setup credentials.

    def reply(self, value):
        data = json.dumps(value).encode()
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        global STREAMING, CURRENT_JPEG
        path = urlparse(self.path)
        if path.path == "/test/reset":
            with LOCK:
                STATE.clear()
                STATE.update(DEFAULT)
                STREAMING = True
                CURRENT_JPEG = JPEG
            self.reply(dict(saved=True))
        elif path.path == "/test/frame":
            CURRENT_JPEG = FACE if parse_qs(path.query).get("kind", [""])[0] == "face" else JPEG
            self.reply(dict(ok=True))
        elif path.path == "/test/stream":
            STREAMING = parse_qs(path.query).get("enabled", ["1"])[0] == "1"
            self.reply(dict(streaming=STREAMING))
        elif path.path == "/api/wifi":
            with LOCK:
                self.reply(dict(STATE))
        elif path.path in ("/health", "/alert"):
            self.reply(dict(ok=True))
        elif path.path == "/stream":
            self.send_response(200)
            self.send_header("Content-Type", "multipart/x-mixed-replace; boundary=frame")
            self.end_headers()
            try:
                while STREAMING:
                    frame = CURRENT_JPEG
                    self.wfile.write(b"--frame\r\nContent-Type: image/jpeg\r\nContent-Length: " + str(len(frame)).encode() + b"\r\n\r\n" + frame + b"\r\n")
                    self.wfile.flush()
                    time.sleep(.1)
            except (BrokenPipeError, ConnectionResetError):
                pass
            self.close_connection = True
        else:
            self.send_error(404)

    def do_POST(self):
        body = json.loads(self.rfile.read(int(self.headers.get("Content-Length", 0))))
        path = urlparse(self.path).path
        if path == "/test/status":
            with LOCK:
                STATE.update(body)
                self.reply(dict(STATE))
        elif path == "/api/wifi":
            with LOCK:
                STATE.update(mode=body.get("mode", "ap"), connected=False)
            self.reply(dict(saved=True, restarting=True))
        else:
            self.send_error(404)


if __name__ == "__main__":
    for port in (18080,):
        server = ThreadingHTTPServer(("127.0.0.1", port), Handler)
        threading.Thread(target=server.serve_forever, daemon=True).start()
    print("ESP fixture on loopback port 18080", flush=True)
    threading.Event().wait()
